#include "VWiiScanner.hpp"
#include <iosuhax.h>
#include <coreinit/filesystem.h>
#include <cstdio>
#include <cerrno>
#include <cstring>
#include <algorithm>
#include <cctype>

namespace {
constexpr const char* TitlesOut="/vol/external01/wiiu/apps/GameVault-WiiU-Exporter/vwii_titles.json";
constexpr const char* TitlesTmp="/vol/external01/wiiu/apps/GameVault-WiiU-Exporter/vwii_titles.json.tmp";
constexpr const char* UsbOut="/vol/external01/wiiu/apps/GameVault-WiiU-Exporter/vwii_usb_diagnostics.json";
constexpr const char* UsbTmp="/vol/external01/wiiu/apps/GameVault-WiiU-Exporter/vwii_usb_diagnostics.json.tmp";
bool Hex8(const char*s){if(!s||std::strlen(s)!=8)return false;for(;*s;++s)if(!std::isxdigit(static_cast<unsigned char>(*s)))return false;return true;}
std::string Upper(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::toupper(c));});return s;}
std::string Category(const std::string&u){if(u=="00000001")return"SYSTEM";if(u=="00010000")return"DISC_TITLE_DATA";if(u=="00010001")return"CHANNEL_OR_WIIWARE_VC";if(u=="00010002")return"SYSTEM_CHANNEL";if(u=="00010004")return"GAME_CHANNEL";if(u=="00010005")return"DLC";if(u=="00010008")return"HIDDEN_CHANNEL";return"OTHER";}
std::string AsciiId(const std::string&hex){std::string out;for(size_t i=0;i+1<hex.size();i+=2){char c=static_cast<char>(std::strtoul(hex.substr(i,2).c_str(),nullptr,16));out.push_back(std::isprint(static_cast<unsigned char>(c))?c:'.');}return out;}
uint16_t BE16(const unsigned char*p){return static_cast<uint16_t>((p[0]<<8)|p[1]);}
uint32_t BE32(const unsigned char*p){return (uint32_t(p[0])<<24)|(uint32_t(p[1])<<16)|(uint32_t(p[2])<<8)|p[3];}
uint64_t BE64(const unsigned char*p){return (uint64_t(BE32(p))<<32)|BE32(p+4);}
size_t SignedBodyOffset(uint32_t sig){if(sig==0x00010000)return 0x240;if(sig==0x00010001)return 0x140;if(sig==0x00010002)return 0x80;return 0;}
void JsonString(FILE*f,const std::string&v){fputc('"',f);for(unsigned char c:v){switch(c){case'"':fputs("\\\"",f);break;case'\\':fputs("\\\\",f);break;case'\n':fputs("\\n",f);break;case'\r':fputs("\\r",f);break;case'\t':fputs("\\t",f);break;default:if(c<0x20)fprintf(f,"\\u%04X",c);else fputc(c,f);}}fputc('"',f);}
std::vector<std::string> ReadNames(int fsa,const std::string&path,int32_t&status,size_t limit=256){std::vector<std::string>names;int h=-1;status=IOSUHAX_FSA_OpenDir(fsa,path.c_str(),&h);if(status<0)return names;FSDirectoryEntry e{};while(names.size()<limit&&IOSUHAX_FSA_ReadDir(fsa,h,&e)>=0){if(e.name[0]=='.')continue;names.emplace_back(e.name);}IOSUHAX_FSA_CloseDir(fsa,h);return names;}
uint32_t CountContent(int fsa,const std::string&path){int32_t status=0;auto names=ReadNames(fsa,path,status);if(status<0)return 0;uint32_t n=0;for(const auto&s:names)if(s.size()>=4&&s.substr(s.size()-4)==".app")++n;return n;}
void DecodeTmd(int fsa,VWiiTitle&t){int fh=-1;t.tmdOpenStatus=IOSUHAX_FSA_OpenFile(fsa,t.tmdPath.c_str(),"r",&fh);if(t.tmdOpenStatus<0)return;FSStat stat{};if(IOSUHAX_FSA_StatFile(fsa,fh,&stat)>=0)t.tmdSize=stat.size;unsigned char buf[0x220]{};int got=IOSUHAX_FSA_ReadFile(fsa,buf,1,sizeof(buf),fh,0);IOSUHAX_FSA_CloseFile(fsa,fh);if(got<4)return;size_t b=SignedBodyOffset(BE32(buf));if(!b||size_t(got)<b+0xA2)return;t.systemVersion=BE64(buf+b+0x44);t.tmdTitleId=BE64(buf+b+0x4C);t.titleType=BE32(buf+b+0x54);t.groupId=BE16(buf+b+0x58);t.regionCode=BE16(buf+b+0x5C);t.accessRights=BE32(buf+b+0x98);t.titleVersion=BE16(buf+b+0x9C);t.tmdContentCount=BE16(buf+b+0x9E);t.bootIndex=BE16(buf+b+0xA0);t.tmdDecoded=true;}
void EnumerateGroup(int fsa,const std::string&upperName,VWiiScanResult&r){const std::string upper=Upper(upperName),root=r.volumePath+"/title/"+upperName;int32_t st=0;auto names=ReadNames(fsa,root,st);if(st<0)return;for(const auto&name:names){if(!Hex8(name.c_str()))continue;VWiiTitle t;t.upperId=upper;t.lowerId=Upper(name);t.titleId=t.upperId+t.lowerId;t.asciiId=AsciiId(t.lowerId);t.category=Category(t.upperId);t.titlePath=root+"/"+name;t.tmdPath=t.titlePath+"/content/title.tmd";DecodeTmd(fsa,t);t.contentCount=CountContent(fsa,t.titlePath+"/content");r.titles.push_back(std::move(t));}}
void ProbeUsb(int fsa,const char*dev,const char*vol,VWiiScanResult&r){VWiiUsbProbe p;p.devicePath=dev;p.volumePath=vol;p.rootPath=vol;p.wbfsPath=std::string(vol)+"/wbfs";p.mountStatus=IOSUHAX_FSA_Mount(fsa,dev,vol,FSA_MOUNTFLAGS_GLOBAL,nullptr,0);p.rootEntries=ReadNames(fsa,p.rootPath,p.rootOpenStatus,100);p.rootOpened=p.rootOpenStatus>=0;p.wbfsEntries=ReadNames(fsa,p.wbfsPath,p.wbfsOpenStatus,300);p.wbfsOpened=p.wbfsOpenStatus>=0;r.usbProbes.push_back(std::move(p));}
bool Finish(FILE*f,const char*tmp,const char*out,std::string&error){if(fflush(f)||ferror(f)){error=std::string("write: ")+strerror(errno);fclose(f);remove(tmp);return false;}if(fclose(f)){error=std::string("close: ")+strerror(errno);remove(tmp);return false;}remove(out);if(rename(tmp,out)){error=std::string("rename: ")+strerror(errno);remove(tmp);return false;}return true;}
}
VWiiScanResult ScanVWiiTitles(){VWiiScanResult r;r.iosuhaxMcpStatus=IOSUHAX_Open("/dev/mcp");if(r.iosuhaxMcpStatus<0){r.iosuhaxDefaultStatus=IOSUHAX_Open(nullptr);if(r.iosuhaxDefaultStatus<0){r.error="IOSUHAX_Open failed";return r;}}r.fsaHandle=IOSUHAX_FSA_Open();if(r.fsaHandle<0){r.error="IOSUHAX_FSA_Open failed";IOSUHAX_Close();return r;}r.mountStatus=IOSUHAX_FSA_Mount(r.fsaHandle,r.devicePath.c_str(),r.volumePath.c_str(),FSA_MOUNTFLAGS_GLOBAL,nullptr,0);int32_t st=0;auto groups=ReadNames(r.fsaHandle,r.volumePath+"/title",st);if(st>=0){r.available=true;for(const auto&g:groups)if(Hex8(g.c_str()))EnumerateGroup(r.fsaHandle,g,r);}else r.error="Open /title failed";ProbeUsb(r.fsaHandle,"/dev/usb01","/vol/gamevault_vwii_usb01",r);ProbeUsb(r.fsaHandle,"/dev/usb02","/vol/gamevault_vwii_usb02",r);std::sort(r.titles.begin(),r.titles.end(),[](const auto&a,const auto&b){return a.titleId<b.titleId;});IOSUHAX_FSA_Close(r.fsaHandle);IOSUHAX_Close();return r;}
bool ExportVWiiDiagnostics(const VWiiScanResult&r,std::string&error){error.clear();FILE*f=fopen(TitlesTmp,"wb");if(!f){error="open titles output failed";return false;}fputs("{\n  \"schemaVersion\": 2,\n  \"exporterVersion\": \"0.2.0-dev6\",\n  \"platform\": \"VWII\",\n",f);fprintf(f,"  \"available\": %s,\n  \"titleCount\": %u,\n  \"titles\": [\n",r.available?"true":"false",unsigned(r.titles.size()));for(size_t i=0;i<r.titles.size();++i){const auto&t=r.titles[i];fputs("    {\"titleId\": ",f);JsonString(f,t.titleId);fputs(", \"asciiId\": ",f);JsonString(f,t.asciiId);fputs(", \"category\": ",f);JsonString(f,t.category);fputs(", \"titlePath\": ",f);JsonString(f,t.titlePath);fprintf(f,", \"tmdDecoded\": %s, \"tmdSize\": %llu, \"systemVersion\": %llu, \"tmdTitleId\": \"%016llX\", \"titleType\": %u, \"groupId\": %u, \"regionCode\": %u, \"accessRights\": %u, \"titleVersion\": %u, \"tmdContentCount\": %u, \"bootIndex\": %u, \"contentCount\": %u}%s\n",t.tmdDecoded?"true":"false",(unsigned long long)t.tmdSize,(unsigned long long)t.systemVersion,(unsigned long long)t.tmdTitleId,t.titleType,t.groupId,t.regionCode,t.accessRights,t.titleVersion,t.tmdContentCount,t.bootIndex,t.contentCount,i+1<r.titles.size()?",":"");}fputs("  ]\n}\n",f);if(!Finish(f,TitlesTmp,TitlesOut,error))return false;f=fopen(UsbTmp,"wb");if(!f){error="open usb output failed";return false;}fputs("{\n  \"schemaVersion\": 1,\n  \"exporterVersion\": \"0.2.0-dev6\",\n  \"platform\": \"WII\",\n  \"probes\": [\n",f);for(size_t i=0;i<r.usbProbes.size();++i){const auto&p=r.usbProbes[i];fputs("    {\"devicePath\": ",f);JsonString(f,p.devicePath);fputs(", \"volumePath\": ",f);JsonString(f,p.volumePath);fprintf(f,", \"mountStatus\": %d, \"rootOpenStatus\": %d, \"rootOpened\": %s, \"wbfsOpenStatus\": %d, \"wbfsOpened\": %s, \"rootEntries\": [",p.mountStatus,p.rootOpenStatus,p.rootOpened?"true":"false",p.wbfsOpenStatus,p.wbfsOpened?"true":"false");for(size_t j=0;j<p.rootEntries.size();++j){if(j)fputc(',',f);JsonString(f,p.rootEntries[j]);}fputs("], \"wbfsEntries\": [",f);for(size_t j=0;j<p.wbfsEntries.size();++j){if(j)fputc(',',f);JsonString(f,p.wbfsEntries[j]);}fprintf(f,"]}%s\n",i+1<r.usbProbes.size()?",":"");}fputs("  ]\n}\n",f);return Finish(f,UsbTmp,UsbOut,error);}
